package com.archos.mediacenter.video.player;

import android.app.*;
import android.graphics.*;
import android.graphics.drawable.Drawable;
import android.view.*;
import android.widget.*;
import com.archos.mediacenter.video.leanback.*;
import java.util.*;
import java.util.function.IntConsumer;

/** Image B main panel and independent Image A1 track popup over retained player callbacks. */
final class PlaybackSubtitlePanel extends LinearLayout {
    static final int[] COLOURS={Color.WHITE,0xffffc93c,0xff19e6e6,0xff4cc554,0xfff06a9b};
    static final class Track {final String label,language;final boolean selected,enabled;final Runnable select;Track(String label,String language,boolean selected,boolean enabled,Runnable select){this.label=label;this.language=language;this.selected=selected;this.enabled=enabled;this.select=select;}}
    interface Backend {int get(String key);void set(String key,int value);List<Track> tracks();void download();boolean available();default Runnable chooseFile(){return null;}}
    private final Activity owner;private final Backend backend;private final SubtitlePanelStyle style;
    private final LinearLayout body,tabs;private final List<Runnable> bindings=new ArrayList<>();private Dialog popup;private LinearLayout popupRows;private LinearLayout trackRow;
    PlaybackSubtitlePanel(Activity owner,Backend backend,IntConsumer switchTab){
        super(owner);this.owner=owner;this.backend=backend;style=new SubtitlePanelStyle(owner,true);setOrientation(VERTICAL);setPadding(style.px(44),style.px(24),style.px(44),style.px(30));setBackground(style.surface(0xf5050b14,0xff4f8fcb,36));setTag("subtitles.main");
        LinearLayout title=new LinearLayout(owner);title.setGravity(Gravity.CENTER_VERTICAL);title.addView(style.icon("settings.gear",52));TextView heading=style.text("Playback Settings",40);heading.setTypeface(null,Typeface.BOLD);heading.setPadding(style.px(24),0,0,0);title.addView(heading);LayoutParams titleSize=new LayoutParams(-1,style.px(76));addView(title,titleSize);
        tabs=new LinearLayout(owner);tabs.setBaselineAligned(false);String[] names={"Subtitles","Audio","Video","More"},icons={"cc","audio","video","settings"};int[] ids={1,0,2,3};
        for(int i=0;i<4;i++){final int index=i;LinearLayout tab=style.row("playback.tab:"+ids[i]);tab.setMinimumHeight(style.px(67));tab.setPadding(style.px(10),0,style.px(10),0);tab.setGravity(Gravity.CENTER);tab.addView(style.icon(icons[i],38));TextView text=style.text(names[i],28);text.setSingleLine(true);text.setPadding(style.px(12),0,0,0);text.setTypeface(null,Typeface.BOLD);tab.addView(text);tab.setBackground(tabSurface(i==0));tab.setSelected(index==0);tab.setOnClickListener(v->{if(index!=0)switchTab.accept(ids[index]);});tab.setOnFocusChangeListener((v,focused)->{if(focused&&index!=0)switchTab.accept(ids[index]);});tab.setOnKeyListener((v,key,event)->{if(event.getAction()!=KeyEvent.ACTION_DOWN)return false;if(key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_RIGHT){tabs.getChildAt(Math.max(0,Math.min(3,index+(key==KeyEvent.KEYCODE_DPAD_LEFT?-1:1)))).requestFocus();return true;}if(key==KeyEvent.KEYCODE_DPAD_DOWN){bodyFocus();return true;}return key==KeyEvent.KEYCODE_DPAD_UP;});LayoutParams size=new LayoutParams(0,-2,i==0?1.2f:1);if(i>0)size.leftMargin=style.px(16);tabs.addView(tab,size);}
        addView(tabs,new LayoutParams(-1,-2));ScrollView scroll=new ScrollView(owner);scroll.setVerticalScrollBarEnabled(true);scroll.setSmoothScrollingEnabled(false);scroll.setFocusable(false);body=new LinearLayout(owner);body.setOrientation(VERTICAL);scroll.addView(body);LayoutParams area=new LayoutParams(-1,0,1);area.topMargin=style.px(18);addView(scroll,area);
        section("SUBTITLE SELECTION");toggle("enabled","cc","Subtitles");
        trackRow=row("track","list","Subtitle Track");TextView active=style.text("",28);active.setSingleLine(true);active.setEllipsize(android.text.TextUtils.TruncateAt.END);trackRow.addView(active,new LayoutParams(0,-2,1));TextView arrow=style.text(" ›",38);trackRow.addView(arrow);bindings.add(()->{Track selected=null;for(Track t:backend.tracks())if(t.selected)selected=t;active.setText(selected==null?"None":selected.label);PreviewLanguageIcon.apply(active,selected==null?null:selected.language);});trackRow.setOnClickListener(v->tracks());
        LinearLayout download=row("download","download","Download Subtitles");TextView find=style.text("Find & Download   ›",28);download.addView(find);download.setOnClickListener(v->backend.download());
        section("SUBTITLE APPEARANCE");choices("size","size","Text Size",new String[]{"Small","Medium","Large"},new int[]{25,50,75});
        swatches();choices("position","position","Vertical Position",new String[]{"Bottom","Middle","Top"},new int[]{0,128,255});
        toggle("outline","outline","Outline");toggle("background","background","Background");choices("opacity","opacity","Background Opacity",new String[]{"0%","25%","50%","75%","100%"},new int[]{0,64,128,191,255});
        LinearLayout delay=row("delay","time","Subtitle Delay");TextView amount=style.text("",28);amount.setGravity(Gravity.CENTER);TextView minus=style.text("−",40),plus=style.text("+",40);delay.addView(minus);delay.addView(amount,new LayoutParams(style.px(155),-2));delay.addView(plus);bindings.add(()->amount.setText(String.format(Locale.ROOT,"%d ms",backend.get("delay"))));delay.setOnClickListener(v->{backend.set("delay",backend.get("delay")+100);refresh();});delay.setOnKeyListener((v,key,event)->{if(event.getAction()==KeyEvent.ACTION_DOWN&&(key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_RIGHT)){backend.set("delay",backend.get("delay")+(key==KeyEvent.KEYCODE_DPAD_LEFT?-100:100));refresh();return true;}return upToTab(delay,key,event);});refresh();
    }
    private Drawable tabSurface(boolean selected){android.graphics.drawable.StateListDrawable d=new android.graphics.drawable.StateListDrawable();d.addState(new int[]{android.R.attr.state_focused},style.surface(0xcc0b2a4a,0xff2fb6ff,18));d.addState(new int[]{},style.surface(selected?0x990b2a4a:Color.TRANSPARENT,0xff2a4a6b,18));return d;}
    void focusTab(){tabs.getChildAt(0).requestFocus();}
    private void bodyFocus(){for(int i=0;i<body.getChildCount();i++)if(body.getChildAt(i).isFocusable()&&body.getChildAt(i).requestFocus())return;}
    private boolean upToTab(View row,int key,KeyEvent event){if(event.getAction()==KeyEvent.ACTION_DOWN&&key==KeyEvent.KEYCODE_DPAD_UP){View next=FocusFinder.getInstance().findNextFocus(body,row,View.FOCUS_UP);if(next==null||next==row){focusTab();return true;}}return false;}
    private void section(String title){TextView label=style.text(title,26);label.setTextColor(0xff9cc9f0);label.setTypeface(null,Typeface.BOLD);label.setPadding(0,style.px(18),0,style.px(8));body.addView(label);style.rule(body);}
    private LinearLayout row(String key,String icon,String title){LinearLayout row=style.row("subtitles.row."+key);row.addView(style.icon(icon,44));TextView label=style.text(title,28);label.setTypeface(null,Typeface.BOLD);label.setPadding(style.px(22),0,style.px(12),0);row.addView(label,new LayoutParams(0,-2,1));row.setContentDescription(title);row.setOnKeyListener((v,k,e)->upToTab(row,k,e));body.addView(row,new LayoutParams(-1,-2));style.rule(body);return row;}
    private void toggle(String key,String icon,String label){LinearLayout row=row(key,icon,label);ImageView value=new ImageView(owner);row.addView(value,new LayoutParams(style.px(82),style.px(44)));bindings.add(()->{boolean on=backend.get(key)!=0;value.setImageDrawable(new Switch(on));row.setContentDescription(label+", "+(on?"On":"Off"));});row.setOnClickListener(v->{backend.set(key,backend.get(key)==0?1:0);refresh();});}
    private void choices(String key,String icon,String title,String[] labels,int[] values){LinearLayout row=row(key,icon,title);LinearLayout choices=new LinearLayout(owner);choices.setGravity(Gravity.CENTER_VERTICAL);row.addView(choices);TextView[] texts=new TextView[labels.length];
        for(int i=0;i<labels.length;i++){if(i>0){TextView divider=style.text("|",26);divider.setTextColor(0xff8fa4ba);divider.setPadding(style.px(15),0,style.px(15),0);choices.addView(divider);}texts[i]=style.text(labels[i],28);choices.addView(texts[i]);}
        bindings.add(()->{int value=backend.get(key);for(int i=0;i<values.length;i++)texts[i].setTextColor(value==values[i]?0xff00a8ff:Color.WHITE);row.setContentDescription(title+", "+value);});row.setOnClickListener(v->change(key,values,1));row.setOnKeyListener((v,k,e)->{if(e.getAction()==KeyEvent.ACTION_DOWN&&(k==KeyEvent.KEYCODE_DPAD_LEFT||k==KeyEvent.KEYCODE_DPAD_RIGHT)){change(key,values,k==KeyEvent.KEYCODE_DPAD_LEFT?-1:1);return true;}return upToTab(row,k,e);});}
    private void change(String key,int[] values,int direction){int n=-1,current=backend.get(key);for(int i=0;i<values.length;i++)if(current==values[i])n=i;int target=n<0?(direction>0?0:values.length-1):Math.max(0,Math.min(values.length-1,n+direction));backend.set(key,values[target]);refresh();}
    private void swatches(){LinearLayout row=row("colour","palette","Text Colour");ImageView[] colours=new ImageView[COLOURS.length];for(int i=0;i<COLOURS.length;i++){colours[i]=new ImageView(owner);LayoutParams size=new LayoutParams(style.px(48),style.px(48));if(i>0)size.leftMargin=style.px(20);row.addView(colours[i],size);}bindings.add(()->{for(int i=0;i<COLOURS.length;i++){final int color=COLOURS[i];final boolean selected=color==backend.get("colour");colours[i].setImageDrawable(new Drawable(){final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);public void draw(Canvas c){android.graphics.Rect b=getBounds();float radius=Math.min(b.width(),b.height())/2f;p.setStyle(Paint.Style.FILL);p.setColor(color);c.drawCircle(b.exactCenterX(),b.exactCenterY(),radius*.75f,p);if(selected){p.setColor(Color.WHITE);p.setStrokeWidth(style.px(2));p.setStyle(Paint.Style.STROKE);c.drawCircle(b.exactCenterX(),b.exactCenterY(),radius*.94f,p);}}public void setAlpha(int a){p.setAlpha(a);}public void setColorFilter(ColorFilter f){p.setColorFilter(f);}public int getOpacity(){return PixelFormat.TRANSLUCENT;}});}});row.setOnClickListener(v->change("colour",COLOURS,1));row.setOnKeyListener((v,k,e)->{if(e.getAction()==KeyEvent.ACTION_DOWN&&(k==KeyEvent.KEYCODE_DPAD_LEFT||k==KeyEvent.KEYCODE_DPAD_RIGHT)){change("colour",COLOURS,k==KeyEvent.KEYCODE_DPAD_LEFT?-1:1);return true;}return upToTab(row,k,e);});}
    void refresh(){for(Runnable binding:bindings)binding.run();for(int i=0;i<body.getChildCount();i++){View row=body.getChildAt(i);Object tag=row.getTag();if(tag instanceof String&&((String)tag).startsWith("subtitles.row.")&&!tag.equals("subtitles.row.download")&&!tag.equals("subtitles.row.track")){boolean enabled=backend.available()&&(!tag.equals("subtitles.row.delay")||backend.get("enabled")!=0);row.setEnabled(enabled);row.setAlpha(enabled?1f:.45f);}}
        if(popupRows!=null){List<Track> tracks=backend.tracks();for(int i=0;i<Math.min(tracks.size(),popupRows.getChildCount()/2);i++){ViewGroup row=(ViewGroup)popupRows.getChildAt(i*2);row.getChildAt(row.getChildCount()-1).setVisibility(tracks.get(i).selected?VISIBLE:INVISIBLE);}}
    }
    private void tracks(){if(popup!=null)return;SubtitlePanelStyle p=new SubtitlePanelStyle(owner,false);popup=new Dialog(owner);popup.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout panel=p.panel();p.header(panel,"Subtitle Track",this::dismissPopup);ScrollView scroll=new ScrollView(owner);scroll.setSmoothScrollingEnabled(false);popupRows=new LinearLayout(owner);popupRows.setOrientation(VERTICAL);scroll.addView(popupRows);panel.addView(scroll,new LayoutParams(-1,0,1));View initial=null;List<Track> tracks=backend.tracks();
        for(int i=0;i<tracks.size();i++){Track track=tracks.get(i);LinearLayout row=p.row("subtitles.track."+i);row.setMinimumHeight(p.px(82));row.addView(p.icon("cc",62));ImageView flag=new ImageView(owner);flag.setImageDrawable(new PreviewLanguageIcon(owner,PreviewLanguageIcon.providerCode(track.language)));LayoutParams f=new LayoutParams(p.px(66),p.px(46));f.leftMargin=p.px(22);f.rightMargin=p.px(22);row.addView(flag,f);TextView label=p.text(track.label,34);label.setSingleLine(true);label.setEllipsize(android.text.TextUtils.TruncateAt.END);row.addView(label,new LayoutParams(0,-2,1));ImageView check=p.icon("check",34);check.setVisibility(track.selected?VISIBLE:INVISIBLE);row.addView(check);row.setEnabled(track.enabled);row.setFocusable(track.enabled);row.setContentDescription(track.label+(track.selected?", selected":""));row.setOnClickListener(v->{track.select.run();refresh();});popupRows.addView(row);p.rule(popupRows);if(initial==null||track.selected)initial=row;}
        Runnable chooseFile=backend.chooseFile();if(chooseFile!=null){TextView choose=p.text("Choose subtitle file…",28);choose.setTag("subtitles.choose.file");choose.setFocusable(true);choose.setFocusableInTouchMode(true);choose.setPadding(p.px(12),p.px(16),p.px(12),p.px(16));choose.setBackground(p.focus());choose.setOnClickListener(v->chooseFile.run());panel.addView(choose);}
        if(tracks.isEmpty())popupRows.addView(p.text("No subtitle tracks available",28));popup.setOnDismissListener(d->{popup=null;popupRows=null;trackRow.requestFocus();});p.show(popup,panel,p.px(666));if(initial!=null)initial.requestFocus();}
    boolean dismissPopup(){if(popup==null)return false;popup.dismiss();return true;}
    void close(){dismissPopup();}
    int panelWidth(){return style.width;}int panelHeight(){return style.height;}
    private final class Switch extends Drawable {final boolean on;final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);Switch(boolean on){this.on=on;}public void draw(Canvas c){android.graphics.Rect b=getBounds();float h=b.height(),r=h/2;p.setColor(on?0xff0a6cff:0xff526174);c.drawRoundRect(b.left,b.top,b.right,b.bottom,r,r,p);p.setColor(Color.WHITE);c.drawCircle(on?b.right-r:b.left+r,b.exactCenterY(),h*.41f,p);}public void setAlpha(int a){p.setAlpha(a);}public void setColorFilter(ColorFilter f){p.setColorFilter(f);}public int getOpacity(){return PixelFormat.TRANSLUCENT;}}
}
